{
  "title": "Discussion on taxes, domain purchase, and app viability",
  "topics": [
    {
      "id": "tax-filing",
      "title": "Complications in tax filing and declaration checks",
      "claims": [
        {
          "text": "The main difficulty is ensuring correct column calculations in declarations, not just the tax amount.",
          "evidence": [1, 5, 8]
        },
        {
          "text": "The whole procedure can take about an hour with Excel, plus one day per month for reporting.",
          "evidence": [5, 6, 7]
        },
        {
          "text": "A calculator only works with a hryvnia‑based FOP, requiring manual conversion for foreign‑currency transactions.",
          "evidence": [19]
        }
      ]
    },
    {
      "id": "domain-purchase",
      "title": "Domain acquisition status",
      "claims": [
        {
          "text": "No domain has been bought yet.",
          "evidence": [2, 9]
        },
        {
          "text": "Someone suggests buying a calculator first before affording a domain.",
          "evidence": [4]
        }
      ]
    },
    {
      "id": "app-viability",
      "title": "Prospects and challenges of the proposed app",
      "claims": [
        {
          "text": "Web platforms are less profitable than Android/iOS and have poor SEO, making traffic acquisition difficult.",
          "evidence": [11]
        },
        {
          "text": "Successful projects use fast delivery (< 1 week) and a cross‑platform stack like Flutter.",
          "evidence": [12]
        },
        {
          "text": "Before analyzing further, it's necessary to verify that at least ten people would pay the 299 UAH price.",
          "evidence": [20]
        },
        {
          "text": "The app is positioned as a local‑first solution with currency rates updated every 5 minutes, but the paid bundle contains the core functionality.",
          "evidence": [29]
        },
        {
          "text": "The project is described as a low‑effort “free vibe‑code” demo, attracting only curious users; many may not buy.",
          "evidence": [30]
        }
      ]
    }
  ],
  "decisions": [],
  "openQuestions": [
    {
      "text": "Are there at least ten potential customers willing to pay 299 UAH for the app?",
      "evidence": [20]
    }
  ]
}
